using TestExam.Domain;
using TestExam.Repositories;

namespace TestExam;

public class ClienteService
{
    private readonly IClienteRepository _repository;

    public ClienteService(IClienteRepository repository)
    {
        _repository = repository;
    }

    public Task<IEnumerable<Cliente>> GetAllAsync()
    {
        return _repository.GetAllAsync();
    }

    public Task<Cliente?> GetByIdAsync(int id)
    {
        return _repository.GetByIdAsync(id);
    }

    public Task<int> CreateAsync(string nombre, string apellido, string documento, string email, string telefono, int direccionId)
    {
        Validaciones.Required(nombre, nameof(nombre));
        Validaciones.Required(apellido, nameof(apellido));
        Validaciones.Required(documento, nameof(documento));
        Validaciones.Required(email, nameof(email));
        Validaciones.Required(telefono, nameof(telefono));
        Validaciones.Positive(direccionId, nameof(direccionId));

        var cliente = new Cliente
        {
            Nombre = nombre,
            Apellido = apellido,
            Documento = documento,
            Email = email,
            Telefono = telefono,
            DireccionId = direccionId
        };

        return _repository.AddAsync(cliente);
    }

    public Task<bool> UpdateAsync(int id, string nombre, string apellido, string documento, string email, string telefono, int direccionId)
    {
        var cliente = new Cliente
        {
            Id = id,
            Nombre = nombre,
            Apellido = apellido,
            Documento = documento,
            Email = email,
            Telefono = telefono,
            DireccionId = direccionId
        };

        return _repository.UpdateAsync(id, cliente);
    }
}

